@Composable
fun MdIcon(icon: MdIcon, contentDescription: String?, modifier: Modifier = Modifier, tint: Color = Lc.icon, size: Dp = 24.dp) {
    Icon(icon.vector, contentDescription, modifier.size(size), tint = tint)
}
